<?php
if(!defined('ABSPATH'))exit;
function dgs_showcase_defaults(){return array('hero_text'=>'محیطی پویا برای آموزش باکیفیت، پرورش استعدادها و آمادگی برای آینده‌ای روشن.','intro'=>'مدرسه دانشگران در دوره دوم متوسطه، همراه دانش‌آموزان پایه‌های دهم، یازدهم و دوازدهم در مسیر یادگیری، رشد علمی و مهارتی است.','mission'=>'پرورش دانش‌آموزانی دانا، خلاق و مسئولیت‌پذیر و همراهی آنان در مسیر یادگیری و آمادگی برای آینده.','hero_image'=>0,'intro_image'=>0,'director'=>0,'director_text'=>'','facilities'=>'','admission_text'=>'برای آشنایی با شرایط پذیرش و ثبت درخواست، فرم پیش‌ثبت‌نام مدرسه را تکمیل کنید.','gallery_image_0'=>0,'gallery_image_1'=>0,'gallery_image_2'=>0,'gallery_image_3'=>0,'gallery_label_0'=>'کلاس درس','gallery_label_1'=>'آزمایشگاه علوم','gallery_label_2'=>'کتابخانه','gallery_label_3'=>'حیاط مدرسه');}
function dgs_showcase_setting($key){$d=get_option('dgs_showcase',array());return isset($d[$key])&&is_scalar($d[$key])?$d[$key]:(dgs_showcase_defaults()[$key]??'');}
function dgs_showcase_staff(){return get_posts(array('post_type'=>'dgs_teacher','post_status'=>'publish','numberposts'=>30,'meta_key'=>'_dgs_group','meta_value'=>'staff','orderby'=>'menu_order title','order'=>'ASC'));}
function dgs_showcase_image_valid($id){return $id&&wp_attachment_is_image($id)&&in_array(get_post_mime_type($id),array('image/jpeg','image/png','image/webp'),true);}
add_action('admin_menu',function(){add_submenu_page('dgs-setup','محتوای صفحه اصلی و معرفی','صفحه اصلی و معرفی','manage_options','dgs-showcase','dgs_showcase_settings_page');});
add_action('admin_enqueue_scripts',function(){if(($_GET['page']??'')!=='dgs-showcase'||!current_user_can('manage_options'))return;wp_enqueue_media();wp_add_inline_script('media-editor',<<<'DSHJS'
jQuery(function($){$(document).on('click','[data-dsh-media]',function(){var field=$(this).closest('.dsh-media-field'),frame=wp.media({title:'انتخاب تصویر مدرسه',library:{type:'image'},multiple:false});frame.on('select',function(){var a=frame.state().get('selection').first().toJSON();field.find('input').val(a.id);field.find('img').attr('src',a.url).show();});frame.open();});$(document).on('click','[data-dsh-clear]',function(){var f=$(this).closest('.dsh-media-field');f.find('input').val('0');f.find('img').hide();});});
DSHJS
);});
function dgs_showcase_settings_page(){if(!current_user_can('manage_options'))wp_die('دسترسی ندارید.');echo '<div class="wrap" style="max-width:1000px"><h1>محتوای صفحه اصلی و معرفی مدرسه</h1>';if(isset($_GET['saved']))echo '<div class="notice notice-success"><p>اطلاعات ذخیره شد.</p></div>';echo '<p>متن‌ها و عکس‌های این دو صفحه از همین بخش تغییر می‌کنند. اساتید، کادر، اخبار و دانش‌آموز برگزیده از اطلاعات منتشرشده سامانه خوانده می‌شوند. تا انتخاب عکس‌های واقعی، تصاویر طرح به‌صورت نمایشی دیده می‌شوند. فوتر از تنظیمات مشترک قبلی استفاده می‌کند.</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="dgs_showcase_save">'.wp_nonce_field('dgs_showcase','dgs_showcase_nonce',true,false).'<table class="form-table">';
 foreach(array('hero_text'=>'متن بالای صفحه اصلی','intro'=>'درباره مدرسه / معرفی کوتاه','mission'=>'رسالت ما','director_text'=>'معرفی مدیر (خالی باشد از متن رزومه او خوانده می‌شود)','facilities'=>'امکانات واقعی مدرسه؛ هر خط: عنوان | توضیح کوتاه','admission_text'=>'توضیح بخش پیش‌ثبت‌نام') as $key=>$label)echo '<tr><th>'.esc_html($label).'</th><td><textarea name="'.$key.'" rows="4" class="large-text" maxlength="5000">'.esc_textarea(dgs_showcase_setting($key)).'</textarea></td></tr>';
 echo '<tr><th>مدیر مدرسه</th><td><select name="director"><option value="0">انتخاب از کادر منتشرشده</option>';foreach(dgs_showcase_staff() as $p)echo '<option value="'.(int)$p->ID.'" '.selected((string)dgs_showcase_setting('director'),(string)$p->ID,false).'>'.esc_html($p->post_title).'</option>';echo '</select><p class="description">کادر مدرسه از دانشگران ← اساتید و کادر مدرسه، با گروه نمایش staff ثبت می‌شود. تخصص/سمت شامل «معاون» باشد در کادر معاونت نیز قرار می‌گیرد. اطلاعات واقعی مدیر و کادر را وارد کنید.</p></td></tr>';
 foreach(array('hero_image'=>'عکس بنر مدرسه','intro_image'=>'عکس معرفی کوتاه')+array_combine(array('gallery_image_0','gallery_image_1','gallery_image_2','gallery_image_3'),array('گالری ۱','گالری ۲','گالری ۳','گالری ۴')) as $key=>$label){$id=absint(dgs_showcase_setting($key));$src=$id?wp_get_attachment_image_url($id,'medium'):'';echo '<tr><th>'.esc_html($label).'</th><td><div class="dsh-media-field"><input type="number" name="'.$key.'" value="'.$id.'" min="0" style="width:100px"><button type="button" class="button" data-dsh-media>انتخاب عکس از رسانه</button> <button type="button" class="button" data-dsh-clear>حذف انتخاب</button><br><img src="'.esc_url($src).'" alt="پیش‌نمایش" style="max-width:240px;max-height:130px;margin-top:10px;'.(!$src?'display:none':'').'"></div>';if(strpos($key,'gallery_')===0){$idx=substr($key,-1);echo '<p><label>عنوان عکس <input name="gallery_label_'.$idx.'" value="'.esc_attr(dgs_showcase_setting('gallery_label_'.$idx)).'" maxlength="80"></label></p>';}echo '</td></tr>';}
 echo '</table>';submit_button('ذخیره صفحه اصلی و معرفی');echo '</form><p><a class="button" href="'.esc_url(home_url('/')).'">مشاهده صفحه اصلی</a> <a class="button" href="'.esc_url(dgs_page_url('about')).'">مشاهده معرفی مدرسه</a></p></div>';}
add_action('admin_post_dgs_showcase_save',function(){if(!current_user_can('manage_options'))wp_die('دسترسی ندارید.','',array('response'=>403));if(($_SERVER['REQUEST_METHOD']??'')!=='POST')wp_die('روش معتبر نیست.','',array('response'=>405));check_admin_referer('dgs_showcase','dgs_showcase_nonce');$next=array();foreach(dgs_showcase_defaults() as $key=>$default){if(!isset($_POST[$key])||!is_scalar($_POST[$key]))wp_die('اطلاعات فرم کامل یا معتبر نیست.','',array('response'=>400));$v=wp_unslash((string)$_POST[$key]);if(strpos($key,'image')!==false){$id=absint($v);if($id&&!dgs_showcase_image_valid($id))wp_die('تصویر انتخابی JPG/PNG/WebP معتبر نیست.','',array('response'=>400));$next[$key]=$id;}elseif($key==='director'){$id=absint($v);$ids=wp_list_pluck(dgs_showcase_staff(),'ID');if($id&&!in_array($id,$ids,true))wp_die('مدیر باید از کادر منتشرشده باشد.','',array('response'=>400));$next[$key]=$id;}else{$v=sanitize_textarea_field($v);if(dgs_edu_length($v)>(strpos($key,'gallery_label_')===0?80:5000))wp_die('متن بیش از حد طولانی است.','',array('response'=>400));$next[$key]=$v;}}update_option('dgs_showcase',$next,false);if(get_option('dgs_showcase')!==$next)wp_die('ذخیره اطلاعات کامل نشد؛ دوباره تلاش کنید.','',array('response'=>500));foreach(array('home','about') as $key){$pages=get_option('dgs_pages',array());if(!empty($pages[$key]))dgs_catalog_invalidate($pages[$key]);}wp_safe_redirect(admin_url('admin.php?page=dgs-showcase&saved=1'),303);exit;});
add_action('admin_post_nopriv_dgs_showcase_save',function(){wp_die('دسترسی ندارید.','',array('response'=>403));});
